pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // 1. Admissible domain: amounts must be > 0 and withdraw <= deposit
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);

        // Fund contract via fallback (anyone can call it)
        address donor = makeAddr("donor");
        vm.deal(donor, depositAmount);
        vm.prank(donor);
        (bool success,) = address(c).call{value: depositAmount}("");
        require(success, "donation failed");

        // Record owner's balance BEFORE withdrawAll
        address owner = c.owner();
        uint256 ownerBalBefore = owner.balance;
        uint256 contractBalBefore = address(c).balance;

        // Owner calls withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        // 3. Assert: owner's balance increase must equal at least the full prior contract balance.
        assertTrue(owner.balance - ownerBalBefore == contractBalBefore);
    }
}

