pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // restrict to admissible domain: depositAmount must be enough for the balance to be non-trivial,
        // and withdrawAmount must be a valid subset that we will later top up so address(this).balance can cover it.
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount >= 0 && withdrawAmount <= type(uint256).max / 2);

        // Send initial Ether to the contract to have a balance.
        // We need the owner to send funds, so prank as the default owner (address(this) in setUp).
        vm.deal(address(this), depositAmount + 1 ether);
        vm.prank(address(this));
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // Record pre-state: contract balance and owner balance
        uint256 preContractBalance = address(c).balance;
        uint256 preOwnerBalance = address(this).balance;

        // Call withdrawAll as the owner
        vm.prank(address(this));
        c.withdrawAll();

        // Post-state: owner balance must have increased by exactly the pre-contract balance
        uint256 postOwnerBalance = address(this).balance;
        assertTrue(postOwnerBalance == preOwnerBalance + preContractBalance);
    }
}

