pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != c.owner());
        vm.assume(nonOwner != address(0));
        amount = bound(amount, 0, address(c).balance);

        // We must put some Ether into the contract first so it can be drained
        // We use the owner to fund the contract. The owner deposits via a fallback.
        address owner = c.owner();
        vm.deal(owner, amount + 100 ether);
        vm.prank(owner);
        (bool sent,) = address(c).call{value: amount + 100 ether}("");
        require(sent, "funding failed");

        // Record balance before the non-owner attempt
        uint256 balanceBefore = address(c).balance;

        // Non-owner attempts to withdrawAll
        vm.prank(nonOwner);
        bool revertFlag;
        try c.withdrawAll() {
            revertFlag = false;
        } catch {
            revertFlag = true;
        }

        // The general rule: a non-owner call MUST revert (reference behavior) and the balance MUST remain unchanged;
        // the mutant does NOT revert and the balance drops to zero.
        // We assert that the call reverted OR the balance stayed unchanged.
        // Because the reference ALWAYS reverts for non-owner, balanceBefore == address(c).balance is true.
        // The buggy version does not revert, and after the call the balance is zero, breaking the equality.
        assertTrue(revertFlag || balanceBefore == address(c).balance);
    }
}

