    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address target) public {
        // 1. Bound amount to a reasonable range to avoid overflow/EVM revert on transfer
        amount = bound(amount, 0, address(c).balance + 1000 ether);
        // 2. target must not be the contract itself to avoid self-destructing or other issues
        vm.assume(target != address(c));

        // 3. Ensure the owner has enough balance
        address owner = c.owner();
        vm.deal(owner, amount);

        // 4. Owner sends money
        vm.prank(owner);
        c.sendMoney(target, amount);

        // 5. Record balance after sendMoney
        uint256 balanceAfter = address(c).balance;

        // 6. Assert that the owner can withdraw the new balance
        //    The buggy version always reverts on withdraw due to require(false)
        //    We wrap the withdraw call in a try/catch
        bool withdrawSucceeded;
        vm.prank(owner);
        try c.withdraw(balanceAfter) {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }

        // 7. The correct contract must allow the owner to withdraw, buggy contract never does
        assertTrue(withdrawSucceeded);
    }
}

