pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict to non-zero amounts that can be covered by the contract's balance.
        // First ensure the contract has enough ETH to withdraw.
        uint256 balanceBefore = address(c).balance;
        // We will top-up the contract by sending ETH directly via a payable fallback.
        // We need to ensure amount > 0 and amount <= balance after topping up.
        vm.assume(amount > 0);
        // Top-up the contract by sending ETH through the fallback (which also increments depositsCount).
        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool topupOk,) = address(c).call{value: amount}("");
        require(topupOk, "topup failed");

        // Now the contract balance is at least amount.
        uint256 balBeforeWithdraw = address(c).balance;
        // Owner withdraws 'amount'.
        vm.prank(c.owner());
        c.withdraw(amount);
        uint256 balAfterWithdraw = address(c).balance;

        // Rule: contract's ETH balance must decrease by exactly the withdrawn amount.
        assertTrue(balBeforeWithdraw - balAfterWithdraw == amount);
    }
}

