contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address _target, uint _value) public {
        uint depositsBefore = c.depositsCount();
        uint targetBalanceBefore = _target.balance;
        bool success;
        try c.sendMoney(_target, _value) { success = true; } catch { success = false; }
        uint depositsAfter = c.depositsCount();
        uint targetBalanceAfter = _target.balance;
        if (success) {
            assert(depositsAfter == depositsBefore && targetBalanceAfter == targetBalanceBefore + _value);
        } else {
            assert(depositsAfter == depositsBefore + 1 && targetBalanceAfter == targetBalanceBefore);
        }
    }
}
